) as v(k, h, he)
where q.difficulty = 'hell' and md5(q.prompt || '|' || q.code) = v.k;

-- Cek: kolom hint_baru harus sama dengan total. Bila lebih kecil, sebagian soal tidak cocok (mis. teks soal diubah) dan hint lamanya tetap dipakai.
select count(*) as total, count(*) filter (where length(hint) >= 53) as hint_baru from questions where difficulty = 'hell';
